export function findCycle(tasks, adj) {
  const names = [...tasks.keys()].sort()
  const state = new Map() // undefined = unvisited, 1 = active, 2 = done
  const stack = []

  function visit(u) {
    state.set(u, 1)
    stack.push(u)
    const deps = [...adj.get(u)].sort()
    for (const v of deps) {
      const s = state.get(v)
      if (s === 1) {
        const idx = stack.indexOf(v)
        return stack.slice(idx).concat(v)
      } else if (s !== 2) {
        const found = visit(v)
        if (found) return found
      }
    }
    stack.pop()
    state.set(u, 2)
    return null
  }

  for (const name of names) {
    if (state.get(name) === 2) continue
    const found = visit(name)
    if (found) return found
  }
  return null
}

/**
 * Computes start, finish and depth (wave) for every task assuming unlimited
 * workers.
 */
export function computeSchedule(tasks, adj) {
  const start = new Map()
  const depth = new Map()

  function compute(name) {
    if (start.has(name)) return
    const deps = adj.get(name)
    if (deps.size === 0) {
      start.set(name, 0)
      depth.set(name, 0)
      return
    }
    let maxFinish = 0
    let maxDepth = -1
    for (const dep of deps) {
      compute(dep)
      const finish = start.get(dep) + tasks.get(dep)
      if (finish > maxFinish) maxFinish = finish
      if (depth.get(dep) > maxDepth) maxDepth = depth.get(dep)
    }
    start.set(name, maxFinish)
    depth.set(name, maxDepth + 1)
  }

  for (const name of tasks.keys()) compute(name)

  const finish = new Map()
  for (const name of tasks.keys()) finish.set(name, start.get(name) + tasks.get(name))

  return { start, finish, depth }
}

/**
 * Simulates the graph on the given number of workers, using the priority and
 * tie-breaking rules from the task spec.
 */
export function packWorkers(tasks, adj, workerCount) {
  const names = [...tasks.keys()]

  const children = new Map()
  for (const name of names) children.set(name, [])
  for (const name of names) {
    for (const dep of adj.get(name)) children.get(dep).push(name)
  }

  const priority = new Map()
  function computePriority(name) {
    if (priority.has(name)) return priority.get(name)
    const kids = children.get(name)
    let best = 0
    for (const kid of kids) {
      const p = computePriority(kid)
      if (p > best) best = p
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }
  for (const name of names) computePriority(name)

  const workerFreeAt = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])
  const finish = new Map()
  const started = new Set()

  let currentTime = 0
  let completed = 0
  const total = names.length

  while (completed < total) {
    // Assign as much as possible at currentTime.
    for (;;) {
      const ready = []
      for (const name of names) {
        if (started.has(name)) continue
        let allDone = true
        for (const dep of adj.get(name)) {
          const f = finish.get(dep)
          if (f === undefined || f > currentTime) {
            allDone = false
            break
          }
        }
        if (allDone) ready.push(name)
      }
      if (ready.length === 0) break

      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      ready.sort((a, b) => {
        const pa = priority.get(a)
        const pb = priority.get(b)
        if (pa !== pb) return pb - pa
        return a < b ? -1 : a > b ? 1 : 0
      })
      const chosen = ready[0]
      const cost = tasks.get(chosen)
      const finishTime = currentTime + cost
      workerFreeAt[freeWorker] = finishTime
      workerLog[freeWorker].push({ name: chosen, start: currentTime, finish: finishTime })
      started.add(chosen)
      finish.set(chosen, finishTime)
      completed++
    }

    if (completed >= total) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > currentTime && workerFreeAt[i] < next) next = workerFreeAt[i]
    }
    if (next === Infinity) {
      // Should not happen for a valid DAG, but avoid an infinite loop.
      throw new CliError(2, 'internal error: scheduling stalled')
    }
    currentTime = next
  }

  const makespan = names.length === 0 ? 0 : Math.max(0, ...[...finish.values()])
  return { workerLog, makespan }
