  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new CliError(2, 'error: workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw usageError()
}

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const argv = process.argv.slice(2)
  let args
  try {
    args = parseArgs(argv)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(err.message + '\n')
      process.exit(err.code)
    }
    throw err
  }

  const text = readStdin()

  let tasks, adj
  try {
    ;({ tasks, adj } = parseGraph(text))
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write('error: ' + err.message + '\n')
      process.exit(err.code)
    }
    throw err
  }

  const cycle = findCycle(tasks, adj)
  if (cycle) {
    process.stderr.write('error: cycle: ' + cycle.join(' -> ') + '\n')
    process.exit(3)
  }

  if (args.mode === 'waves') {
    const { finish, depth } = computeSchedule(tasks, adj)
    const waves = []
    for (const [name, d] of depth) {
      if (!waves[d]) waves[d] = []
      waves[d].push(name)
    }
    let out = ''
    for (let i = 0; i < waves.length; i++) {
      const names = waves[i].slice().sort()
      out += `wave ${i}: ${names.join(' ')}\n`
    }
    const total = tasks.size === 0 ? 0 : Math.max(0, ...[...finish.values()])
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (args.mode === 'explain') {
    const { start, finish, depth } = computeSchedule(tasks, adj)
    const names = [...tasks.keys()].sort()
    let out = ''
    for (const name of names) {
      out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    const total = tasks.size === 0 ? 0 : Math.max(0, ...[...finish.values()])
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (args.mode === 'pack') {
    const { workerLog, makespan } = packWorkers(tasks, adj, args.workers)
    let out = ''
    for (let i = 0; i < workerLog.length; i++) {
      const entries = workerLog[i].map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
      out += `worker ${i}:${entries}\n`
    }
    out += `makespan ${makespan}\n`
    process.stdout.write(out)
  }
}

main()
